with d as (select value r from jsonb_array_elements($q$[{"steps":[{"text":"Heat the mustard oil in a large pan over medium-high heat until it smokes lightly and settles, this takes about 1 minute. This is important; the oil must announce itself."},{"text":"Add the nigella seeds and let them crackle for a few seconds until fragrant."},{"text":"Add the potatoes and stir to coat in oil. Cook for 3–4 minutes until they begin to colour at the edges."},{"text":"Sprinkle in the turmeric and stir well."},{"text":"Add the green chilli and cook, stirring occasionally, for 8–10 minutes until the potatoes are three-quarters cooked and lightly golden."},{"text":"Mix the poppy seed paste with 2 tbsp water to loosen it slightly. Add to the pan and stir to coat the potatoes evenly. If it seems dry, add another tablespoon of water."},{"text":"Cook, stirring gently now and then, for 5–7 minutes until the potatoes are tender and the paste is no longer raw. The dish should be almost dry, with the potatoes well coated in the dark paste."},{"text":"Taste and adjust salt. Serve warm, scattered with fresh coriander if you wish."}],"id":"4c3d1fc0-d6a7-41bf-b36d-a567a11887bf"},{"notes":["This stew reheats beautifully and tastes even better the next day. Keep in the fridge for up to 3 days.","Serve with crusty bread for soaking up the broth, or with plain white rice.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Heat the oil in a large pot over medium-high heat. Working in batches, brown the lamb on all sides, about 8 minutes total. Set aside."},{"text":"Add the diced onion to the pot and cook, stirring, until soft and golden, about 5 minutes."},{"text":"Return the lamb to the pot and stir in the cumin. Cook for 1 minute until fragrant."},{"text":"Add the tinned tomatoes, breaking them up with the back of a spoon, then pour in the stock and add the lentils. Stir well and bring to a simmer until the liquid is bubbling gently."},{"text":"Reduce the heat to low, cover partially, and simmer for 50 minutes, stirring occasionally. The lentils should be very soft and starting to break down, and the lamb should be tender."},{"text":"Season with salt and pepper to taste. If the stew is too thin, simmer uncovered for a few more minutes until it is thick and the lentils are soft. Serve hot."}],"id":"56aa0ea9-4c71-4ea9-ae3c-e7864e1d9876"},{"notes":["Make ahead: Gumbo tastes even better the next day. Cool completely, refrigerate for up to 3 days, and reheat gently on the stove.","The roux is the foundation, keep the heat medium and stir constantly. A dark roux (not burnt) gives the gumbo its signature flavour and colour.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Melt butter in a large heavy-bottomed pot over medium heat. Add flour and stir constantly, scraping the bottom, until the roux turns deep chocolate brown, about 25–30 minutes. Don't rush it, burnt roux tastes bitter, so keep the heat medium and stay patient."},{"text":"Add the diced onion, celery and capsicum to the roux. Stir and cook until the vegetables begin to soften, about 5 minutes, scraping up any browned bits from the bottom."},{"text":"Stir in the garlic and cook for 1 minute until fragrant."},{"text":"Add the andouille sausage and cook, stirring, for 3–4 minutes until it releases its oil and the edges colour."},{"text":"Add the chicken thighs and turn to coat in the roux. Cook for 2–3 minutes, then pour in the chicken stock. Add the bay leaves and thyme."},{"text":"Bring to a gentle boil, then reduce heat to low. Simmer, partially covered, for 1 hour, stirring occasionally. The chicken should be very tender and the broth rich and dark."},{"text":"Remove from heat. Pull the chicken thighs from the pot, let cool slightly, shred the meat from the bones and return it to the pot. Discard the bay leaves."},{"text":"Taste and season with salt and black pepper."},{"text":"Serve over cooked white rice in wide bowls with a spoon and fork for the broth and meat."}],"id":"ffe5c95f-a653-43e3-a00c-807c38ffb382"},{"notes":["Make ahead: cook the chicken and prepare the ají paste the day before. Reheat gently before serving.","Use leftover roast or poached chicken to save time on a weeknight.","Fresh ají amarillo peppers are best, but bottled paste (found in Latin American shops) works perfectly well.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"23f994d1-1704-4cfa-a48e-47db8f65ebde"},{"notes":["Make ahead: assemble the pastilla up to 2 hours before baking and refrigerate, covered with cling film. Brush with melted butter just before baking.","The eggs must stay soft and creamy, don't cook them through. They'll cook gently in the oven.","Filo dries out quickly. Keep sheets under a damp tea towel until you use them.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Place the chicken breast, quartered onion, ginger, turmeric, cinnamon, salt and pepper in a large pot. Cover with water and bring to a simmer. Cook for 20 minutes until the chicken is cooked through. Remove the chicken, let it cool slightly, then shred the meat finely, discarding the skin. Chop the coriander and parsley and set aside."},{"text":"Toast the almonds in a dry frying pan over medium heat for 2 minutes until fragrant. Add 2 tbsp oil, the cinnamon, sugar and salt. Cook, stirring, for 1 minute, then transfer to a plate to cool."},{"text":"In a small non-stick frying pan, lightly beat the eggs with salt and pepper. Melt 30 g butter and scramble the eggs gently until soft and creamy, about 3 minutes. Transfer to a plate."},{"text":"Preheat the oven to 180°C. In a bowl, gently toss the shredded chicken with the herbs."},{"text":"Lay a sheet of filo on a clean work surface and brush lightly with melted butter. Layer a second sheet on top and brush again. This is your base, it will be half the pastilla."},{"text":"Spread half the scrambled eggs in a rough rectangle on the lower half of the filo stack, leaving a 5 cm border. Top with half the chicken mixture, then half the almonds."},{"text":"Fold the sides of the filo inward, then roll up tightly from the bottom, creating a tight cylinder. Place seam-side down on a baking tray and brush the top with melted butter."},{"text":"Repeat steps 5 to 7 with the remaining filo, eggs, chicken and almonds to make a second pastilla."},{"text":"Bake for 25 to 30 minutes until the pastilla is deep golden brown and crisp."},{"text":"Let rest for 2 minutes, then transfer to a serving plate. Dust generously with icing sugar and cinnamon at the table. Serve hot."}],"id":"96d23ca0-4e21-4045-91e8-82ede59ade0d"},{"notes":["This salsa keeps for up to a week in an airtight container in the fridge.","Don't rush the toasting, low heat brings out the deep, complex flavours that make this salsa special."],"steps":[{"text":"Heat a heavy frying pan or comal over medium-low heat. Place the dried chillies in the pan and toast them, turning every 20 seconds, until fragrant and darkened but not blackened, about 4 to 5 minutes total. They should smell rich and earthy, almost like chocolate."},{"text":"Remove the stems and most of the seeds from the cooled chillies, shaking out what comes loose. Leave a few seeds for heat."},{"text":"In the same dry pan, toast the garlic cloves, turning occasionally, until lightly charred and soft, about 3 minutes."},{"text":"Using a molcajete (lava rock mortar and pestle), grind the toasted chillies, garlic, and salt together in slow, circular motions. Work the pestle in a grinding motion until you reach a coarse paste, this takes patience, but the friction releases the true flavour. Stop when you reach your preferred texture; some like it smooth, some leave it rough."},{"text":"Taste and add more salt if needed. If the salsa is too thick, stir in a few drops of water."}],"id":"33650227-138f-4226-bba5-2fbfdc42a3ae"},{"notes":["Make ahead: cook dried beans the day before, or use quality tinned beans. Refried beans reheat beautifully on the stove with a splash of water.","The texture depends on mashing technique and cook time, not the fat. If they seem too thick after cooling, warm and stir in a little hot water.","Serve with warm tortillas, as part of breakfast, or alongside grilled vegetables."],"steps":[{"text":"Heat the oil in a heavy-bottomed pan over medium heat. Add the diced onion and cook, stirring occasionally, until soft and translucent, about 5 minutes."},{"text":"Add the minced garlic and cook for 1 minute, stirring, until fragrant."},{"text":"Add the drained beans to the pan, stirring to coat them in the oil and aromatics."},{"text":"Mash the beans with the back of a wooden spoon or a potato masher as they warm, breaking down the cell walls gradually. This is the key, you're not trying to purée them all at once, but rather let the starch and pressure do the work over time."},{"text":"Continue cooking and mashing over medium-low heat for about 8–10 minutes, adding splashes of water (or bean cooking liquid if you have it) as needed to reach a creamy, spreadable consistency. The beans should hold together but not be stiff."},{"text":"Taste and season with salt and cumin if using. The beans are ready when they're smooth, glossy, and slightly darker in colour from the slow breakdown of their starches."}],"id":"3d639bf4-e5db-450c-8fd7-190b1a4eb35a"},{"notes":["The filling can be made up to 4 hours ahead and kept in the fridge. Assemble the popiah just before serving so the skin stays soft.","Popiah are best eaten fresh, but you can wrap them tightly in plastic wrap and refrigerate for up to 2 hours. Don't freeze, the skin will crack when thawed.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C. Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Blanch the turnip matchsticks in boiling salted water for 1 minute, then drain well and squeeze dry with a clean cloth. Set aside."},{"text":"Heat the oil in a wok or large pan over high heat. Add the garlic and cook for 30 seconds until fragrant."},{"text":"Add the pork mince and fry, breaking it up as it cooks, for 2 minutes until cooked through."},{"text":"Stir in the chopped prawn and cook for 1 minute until just cooked and still tender."},{"text":"Add the blanched turnip, oyster sauce, soy sauce and salt. Toss everything together for 1 minute, then remove from heat and let cool to room temperature."},{"text":"While the filling cools, make the sauce: stir together the hoisin, sweet chilli sauce, lime juice, sesame oil and minced garlic. Set aside."},{"text":"Lay one popiah skin flat on a clean surface. Spread a thin line of the filling across the middle, don't overfill. Top with a small handful of fresh coriander and a few pieces of spring onion."},{"text":"Fold the two sides of the skin over the filling, then roll tightly from the bottom up, tucking in the sides as you go. Place seam-side down on a plate."},{"text":"Repeat with the remaining skins and filling."},{"text":"Arrange the popiah on a serving plate, sprinkle with crispy fried shallots, and serve with the sauce on the side for dipping."}],"id":"8523f6b4-f6df-4fb7-8814-57f21ab434e5"},{"notes":["Make ahead: shape and refrigerate the patties up to 4 hours before frying.","Serve with a simple green salad or steamed beets, Hamburg style.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Bring a pot of salted water to the boil. Cut the potato into chunks and cook until just tender, about 12 minutes. Drain and let cool slightly."},{"text":"Meanwhile, check the fish for any fine bones and discard. Finely chop the onion."},{"text":"Grate the cooled potato into a large bowl. Finely chop or pulse the fish in a food processor until roughly textured but not a paste, then add to the potato."},{"text":"Add the onion, egg, breadcrumbs, mustard, salt and white pepper. Mix gently with your hands until just combined, don't overwork it."},{"text":"Shape the mixture into 8 patties about 7 cm across and 1.5 cm thick. Rest for 5 minutes if time allows."},{"text":"Heat a thin layer of oil in a large frying pan over medium heat. When hot, fry the patties in two batches, about 3–4 minutes each side, until golden and cooked through. Don't move them around; let them develop a good crust."},{"text":"Serve warm with a dollop of Dijon mustard on the side or a squeeze of lemon."}],"id":"fd74aee6-63f4-4b7f-87b2-4c22b503f587"},{"notes":["Make these up to 4 hours ahead and reheat wrapped in foil in a 180°C oven for 10 minutes.","The dough will keep in the fridge, covered, for up to 2 days. Bring to room temperature before rolling.","Cook pork until it reaches at least 70°C in the thickest part (75°C for mince and sausages)."],"id":"7c675e03-7c7c-4ba7-a33a-2a98499eaee9"},{"notes":["Slice the pork thinly while it's cold, pop it in the freezer for 30 minutes first if it's hard to cut.","Pickled chilies are the soul of this dish. Look for them in a tin in the Asian aisle, not the fresh chilli section.","This reheats beautifully; store leftovers in the fridge and warm gently in a wok or pan with a splash of water.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"id":"c7041581-50ca-4e52-86af-54fa4cf685a1"},{"notes":["The pickled vegetables keep for up to 5 days in the fridge, so you can make them ahead.","Press the tofu well, this is what makes it absorb flavour and fry up crisp. If you skip this step, you will have a sad bánh mì.","Leftover fried tofu keeps in an airtight container for 2 days and can be reheated gently in a low oven."],"id":"47799599-53bd-48e9-a8ff-070dc9349314"},{"steps":[{"text":"Bring a large pot of salted water to the boil. Add the bean sprouts and cook for 4 minutes, they should be tender but still have a slight bite. Drain well and spread on a clean kitchen towel to cool completely."},{"text":"Toast the sesame seeds in a small dry pan over medium heat, stirring often, for 2 minutes until fragrant. Transfer to a mortar and pestle and crush lightly, leaving some seeds whole."},{"text":"In a large bowl, whisk together the soy sauce, sesame oil and ginger. Add the cooled sprouts and toss gently to coat. Taste and adjust salt if needed."},{"text":"Sprinkle the toasted sesame over the top just before serving."}],"id":"53d74f14-3828-4522-b783-238c4ab49e64"},{"notes":["The crust is everything. Don't rush it, you want deep gold, not pale. If it's not crackling by minute 25, turn heat up slightly.","Use day-old cooked chicken if you have it; rotisserie works perfectly. The yoghurt binds everything and keeps the rice from drying out.","Make ahead: prepare the rice and yoghurt mixture up to 4 hours in advance. Cook in the pan just before serving."],"id":"f3c904a6-48d0-4bfe-9a4c-9eabc937bf4c"},{"notes":["The batter must ferment 8 hours or overnight, start the day before.","If you don't have an appam pan, use a shallow non-stick frying pan with a lid; the pancakes will be less lacy but still delicious.","The stew can be made up to 2 days ahead and warmed through before serving.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"fb87136c-432a-4e59-8f8f-4a1e16197b82"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;